import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        new Main().runProgram();
    }

    void runProgram() {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        int n = in.nextInt();
        int k = in.nextInt();
        int[] v = new int[10];
        for (int i = 0; i < k; i++) {
            v[in.nextInt()] = 1;
        }
        int[] result = {1};
        int power = n / 2;
        while (power > 0) {
            if ((power & 1) == 1) {
                result = multiplyPolynomials(result, v, 998244353);
            }
            v = multiplyPolynomials(v, v, 998244353);
            power >>= 1;
        }
        long answer = 0;
        for (int value : result) {
            answer = (answer + (long) value * value) % 998244353;
        }
        out.println(answer);
        out.close();
    }

    int[] multiplyPolynomials(int[] a, int[] b, int mod) {
        int requiredLength = a.length + b.length - 1;
        int n = 1;
        while (n < requiredLength) n <<= 1;

        double[] ar = new double[n], ai = new double[n];
        double[] br = new double[n], bi = new double[n];

        for (int i = 0; i < a.length; i++) {
            long x = ((a[i] % mod) + mod) % mod;
            ar[i] = x & 0x7FFF;
            ai[i] = x >>> 15;
        }
        for (int i = 0; i < b.length; i++) {
            long x = ((b[i] % mod) + mod) % mod;
            br[i] = x & 0x7FFF;
            bi[i] = x >>> 15;
        }

        performFFT(ar, ai, false);
        performFFT(br, bi, false);

        double[] resRe1 = new double[n], resIm1 = new double[n];
        double[] resRe2 = new double[n], resIm2 = new double[n];

        for (int i = 0; i < n; i++) {
            int j = (n - i) & (n - 1);
            double a1r = (ar[i] + ar[j]) * 0.5;
            double a1i = (ai[i] - ai[j]) * 0.5;
            double a2r = (ai[i] + ai[j]) * 0.5;
            double a2i = (ar[j] - ar[i]) * 0.5;

            double b1r = (br[i] + br[j]) * 0.5;
            double b1i = (bi[i] - bi[j]) * 0.5;
            double b2r = (bi[i] + bi[j]) * 0.5;
            double b2i = (br[j] - br[i]) * 0.5;

            resRe1[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
            resIm1[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            resRe2[i] = a1r * b2r - a1i * b2i + a2r * b1r - a2i * b1i;
            resIm2[i] = a1r * b2i + a1i * b2r + a2r * b1i + a2i * b1r;
        }

        performFFT(resRe1, resIm1, true);
        performFFT(resRe2, resIm2, true);

        int[] output = new int[requiredLength];
        for (int i = 0; i < requiredLength; i++) {
            long aa = Math.round(resRe1[i]);
            long bb = Math.round(resRe2[i]);
            long cc = Math.round(resIm1[i]);
            output[i] = (int) ((aa + ((bb % mod) << 15) + ((cc % mod) << 30)) % mod);
        }
        return output;
    }

    void performFFT(double[] re, double[] im, boolean inverse) {
        int n = re.length;
        int shift = 32 - Integer.numberOfTrailingZeros(n);
        for (int i = 1; i < n; i++) {
            int j = Integer.reverse(i << shift);
            if (i < j) {
                double temp = re[i];
                re[i] = re[j];
                re[j] = temp;
                temp = im[i];
                im[i] = im[j];
                im[j] = temp;
            }
        }

        for (int len = 2; len <= n; len <<= 1) {
            int half = len >> 1;
            for (int i = 0; i < n; i += len) {
                for (int j = 0; j < half; j++) {
                    double angle = 2 * Math.PI * j / len;
                    double wRe = Math.cos(angle);
                    double wIm = inverse ? -Math.sin(angle) : Math.sin(angle);

                    double uRe = re[i + j];
                    double uIm = im[i + j];
                    double vRe = re[i + j + half] * wRe - im[i + j + half] * wIm;
                    double vIm = re[i + j + half] * wIm + im[i + j + half] * wRe;

                    re[i + j] = uRe + vRe;
                    im[i + j] = uIm + vIm;
                    re[i + j + half] = uRe - vRe;
                    im[i + j + half] = uIm - vIm;
                }
            }
        }

        if (inverse) {
            double invN = 1.0 / n;
            for (int i = 0; i < n; i++) {
                re[i] *= invN;
                im[i] *= invN;
            }
        }
    }

    static class InputReader {
        private final InputStream inputStream;
        private final byte[] buffer = new byte[1024];
        private int bufferPointer = 0;
        private int bufferLength = 0;

        public InputReader(InputStream inputStream) {
            this.inputStream = inputStream;
        }

        private int readByte() {
            if (bufferLength == -1) throw new RuntimeException();
            if (bufferPointer >= bufferLength) {
                bufferPointer = 0;
                try {
                    bufferLength = inputStream.read(buffer);
                } catch (IOException e) {
                    throw new RuntimeException();
                }
                if (bufferLength <= 0) return -1;
            }
            return buffer[bufferPointer++] & 0xFF;
        }

        public int nextInt() {
            int c = readByte();
            while (c <= 32) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int value = 0;
            while (c > 32) {
                if (c < '0' || c > '9') throw new RuntimeException();
                value = value * 10 + c - '0';
                c = readByte();
            }
            return value * sign;
        }
    }
}
